import re

def validate_braces(format_str):
    '''Check that all fields are properly enclosed in matching braces.'''
    i = 0
    while i < len(format_str):
        if format_str[i] == '{':
            # Check if next char is also { (escaped brace)
            if i + 1 < len(format_str) and format_str[i+1] == '{':
                # Find the matching }}
                j = format_str.find('}}', i + 2)
                if j == -1:
                    raise ValueError(f\"unclosed escaped brace in pattern: {format_str!r}\")
                i = j + 2  # Skip past }}
                continue

            # This is a potential field start - find the matching }
            j = format_str.find('}', i + 1)
            if j == -1:
                raise ValueError(f\"unclosed field in pattern: {format_str!r}\")

            # Move past the closing brace
            i = j + 1
            # If there's another } immediately after, skip it too (escaped })
            if i < len(format_str) and format_str[i] == '}':
                i += 1
        elif format_str[i] == '}':
            # Orphaned closing brace without opening
            raise ValueError(f\"orphaned closing brace in pattern: {format_str!r}\")
        else:
            i += 1

    return True

# Test cases including edge cases  
test_cases = [
    ('{name}', True),
    ('{name', False),
    ('hello {world}', True),  
