    ('a{{b}}c', True),          # escaped braces in middle
    ('{name}}extra', True),     # field followed by literal }
    ('a{b', False),             # unclosed
    ('abc', True),              # plain text
    ('{{', False),              # unclosed escaped brace
    ('}}', True),               # just escaped closing brace
]

